+                                                     builder.ldc("YYYY");
+                                                     builder.areturn();
+                                                 });
+        System.out.println("Result: " + (new ShouldBeTransformed()));
+    }
+
+    static class ShouldBeTransformed {
+        public String toString() {
+            return "XXXX"; // Will be changed to "YYYY" with class redefinition
+        }
+    }
+}

